using CertDesk.Common; using CertDesk.Forms; using CertDesk.Models; using CertDesk.Services;
namespace CertDesk.Views;
public partial class TokensView:UserControl{ readonly CurrentUser u; DataGridView grid=new(); TextBox q=new(); ComboBox st=new(); public TokensView(CurrentUser user){u=user;InitializeComponent();Build();LoadData();} int Id=>grid.CurrentRow==null?0:Convert.ToInt32(grid.CurrentRow.Cells["ID"].Value); void Build(){BackColor=UiTheme.Light; q.SetBounds(15,15,160,25); st.SetBounds(185,15,120,25); st.Items.AddRange(new object[]{"Все","storage","issued","damaged","written_off"});st.SelectedIndex=0; var add=B("Добавить"),edit=B("Изменить"),iss=B("Выдать"),ret=B("Вернуть"),dam=B("Поврежден"),wo=B("Списать"),refb=B("Обновить"); Flow(315,add,edit,iss,ret,dam,wo,refb); grid.SetBounds(15,60,1000,560);grid.Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right|AnchorStyles.Bottom;UiTheme.ApplyGridStyle(grid);Controls.AddRange(new Control[]{q,st,add,edit,iss,ret,dam,wo,refb,grid}); q.TextChanged+=(_,__)=>LoadData();st.SelectedIndexChanged+=(_,__)=>LoadData();refb.Click+=(_,__)=>LoadData();add.Click+=(_,__)=>Save(new TokenEditForm(),false);edit.Click+=(_,__)=>{var t=TokenService.GetById(Id);if(t!=null)Save(new TokenEditForm(t),true);};iss.Click+=(_,__)=>{using var f=new TokenIssueForm(); if(Id>0&&f.ShowDialog()==DialogResult.OK){TokenService.Issue(Id,f.EmployeeId,f.ActNumber,f.Comment,u);LoadData();}};ret.Click+=(_,__)=>{if(Id>0&&MessageHelper.Confirm("Вернуть токен?")){TokenService.Return(Id,u);LoadData();}};dam.Click+=(_,__)=>{if(Id>0&&MessageHelper.Confirm("Отметить токен поврежденным?")){TokenService.MarkDamaged(Id,u);LoadData();}};wo.Click+=(_,__)=>{if(Id>0&&MessageHelper.Confirm("Списать токен?")){TokenService.WriteOff(Id,u);LoadData();}}; if(!RoleGuard.CanManageTokens(u)) add.Enabled=edit.Enabled=iss.Enabled=ret.Enabled=dam.Enabled=wo.Enabled=false;} Button B(string t){var b=new Button{Text=t,Top=13,Width=95};UiTheme.ApplyButtonStyle(b);return b;} void Flow(int x,params Button[] bs){foreach(var b in bs){b.Left=x;x+=101;}} void Save(TokenEditForm f,bool edit){try{if(f.ShowDialog()==DialogResult.OK){if(edit)TokenService.Update(f.Token,u);else TokenService.Create(f.Token,u);LoadData();}}catch(Exception ex){MessageHelper.Error("Не удалось сохранить. Проверьте уникальность номера. "+ex.Message);}} void LoadData()=>grid.DataSource=TokenService.Search(q.Text,st.Text);}
